{"question":"Describe each listed object in one or two plain sentences: what it holds or does and what it is for, as a business reader would understand it. Do not list its columns or tables. Use only the metadata given. Objects: dbo.department_order_summary, dbo.patient_encounter_summary, dbo.count_patient_encounters, dbo.patient_order_total","metadata":{"structural":{"objects":[{"name":"dbo.department_order_summary","kind":"view","columns":["department_id","order_amount","order_count"],"keys":[],"parameters":[],"returns":[],"reads":["dbo.departments","dbo.orders"],"writes":[],"calls":[]},{"name":"dbo.patient_encounter_summary","kind":"view","columns":["encounter_count","patient_id"],"keys":[],"parameters":[],"returns":[],"reads":["dbo.encounters","dbo.patients"],"writes":[],"calls":[]},{"name":"dbo.count_patient_encounters","kind":"procedure","columns":[],"keys":[],"parameters":["@patient_id"],"returns":[],"reads":["dbo.encounters"],"writes":[],"calls":[]},{"name":"dbo.patient_order_total","kind":"procedure","columns":[],"keys":[],"parameters":["@patient_id"],"returns":[],"reads":["dbo.encounters","dbo.orders"],"writes":[],"calls":[]}]},"descriptive":{"definition dbo.department_order_summary":"CREATE VIEW dbo.department_order_summary AS
SELECT d.department_id, COUNT_BIG(o.order_id) AS order_count, COALESCE(SUM(o.amount),<number>) AS order_amount
FROM dbo.departments d LEFT JOIN dbo.orders o ON o.department_id=d.department_id
GROUP BY d.department_id;
","definition dbo.patient_encounter_summary":"
CREATE VIEW dbo.patient_encounter_summary AS
SELECT p.patient_id, COUNT_BIG(e.encounter_id) AS encounter_count
FROM dbo.patients p LEFT JOIN dbo.encounters e ON e.patient_id=p.patient_id
GROUP BY p.patient_id;
","definition dbo.count_patient_encounters":"CREATE   PROCEDURE dbo.count_patient_encounters @patient_id int AS
BEGIN
  SET NOCOUNT ON;
  SELECT COUNT_BIG(*) AS encounter_count FROM dbo.encounters WHERE patient_id=@patient_id;
END;
","definition dbo.patient_order_total":"CREATE   PROCEDURE dbo.patient_order_total @patient_id int AS
BEGIN
  SET NOCOUNT ON;
  SELECT COALESCE(SUM(o.amount),<number>) AS order_total
  FROM dbo.orders o JOIN dbo.encounters e ON e.encounter_id=o.encounter_id
  WHERE e.patient_id=@patient_id;
END;
"}},"identifier_fingerprints":[]}
